export function createOrder({ customerId, lines }) {
  if (!Array.isArray(lines) || lines.length === 0)
    throw new DomainError('cannot open an empty order');

  const state = { orderId: newOrderId(), customerId, lines: [...lines], status: 'draft' };
  return Object.freeze({
    get id() { return state.orderId; },
    place() { state.status = 'placed'; },
  });
}
